{"findings":[{"tipo":"GC","causa_raiz":"Alocação excessiva de memória no heap gerenciado dentro do Update(), gerando quase 8 MB por frame via concatenação repetida de strings (s += i.ToString()) e alocação de arrays descartáveis. Como strings são imutáveis em C#, cada ciclo cria novos objetos de texto no heap, forçando coletas de Garbage Collector que travam a CPU por 24.57ms.","codigo_refatorado":"using System;
using System.Text;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;
        public GameObject testPrefab;

        [Range(1, 20)]
        public float spawnRadius = 10f;
        [Range(1, 50)]
        public int cubesPerFrame = 1;
        public bool useUniqueMaterials = false;
        [Range(1, 512)]
        public int cpuScansPerFrame = 1;
        public int emptyObjects = 0;
        public int gcConcatIterations = 1000;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;
        [Range(0, 2000)]
        public int prepopulateCount = 0;

        private StringBuilder _sb = new StringBuilder(4096);
        private MaterialPropertyBlock _propBlock;
        private static readonly int ColorPropertyId = Shader.PropertyToID("_Color");

        private void Awake()
        {
            _propBlock = new MaterialPropertyBlock();
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                new GameObject("Empty_" + i);
            }

            if (overdrawLayers > 0 && overdrawMaterial != null)
            {
                BuildOverdrawLayers();
            }
        }

        private void BuildOverdrawLayers()
        {
            Camera cam = Camera.main;
            if (cam == null) return;
            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;
            for (int i = 0; i < overdrawLayers; i++)
            {
                float d = cam.nearClipPlane + 0.05f + i * 0.001f;
                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;
                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);
                Destroy(quad.GetComponent<Collider>());
                quad.name = "Overdraw_" + i;
                quad.transform.SetParent(cam.transform, false);
                quad.transform.localPosition = new Vector3(0f, 0f, d);
                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);
                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;
            }
        }

        private void Update()
        {
            if (stressGc)
            {
                _sb.Clear();
                for (int i = 0; i < gcConcatIterations; i++)
                {
                    _sb.Append(i);
                }
            }

            if (stressCpu)
            {
                // Evita GameObject.FindObjectsOfType no Update pois varre toda a cena
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(testPrefab, UnityEngine.Random.insideUnitSphere * spawnRadius, Quaternion.identity);

            if (useUniqueMaterials)
            {
                var rend = clone.GetComponent<Renderer>();
                if (rend != null)
                {
                    rend.GetPropertyBlock(_propBlock);
                    _propBlock.SetColor(ColorPropertyId, new Color(UnityEngine.Random.value, UnityEngine.Random.value, UnityEngine.Random.value));
                    rend.SetPropertyBlock(_propBlock);
                }
            }
        }
    }
}","explicacao_didatica":"Em C#, as strings são imutáveis: cada vez que você faz 'texto += algo', o computador não altera o texto existente, ele cria uma cópia inteiramente nova na memória (heap). Fazer isso centenas de vezes a cada frame enche a memória muito rápido. Quando a memória enche, o Unity precisa parar o jogo por vários milissegundos para executar a Coleta de Lixo (Garbage Collector), gerando travamentos visíveis (engasgos de quase 25ms). Usamos 'StringBuilder' reutilizável para manipular textos sem alocar lixo e 'MaterialPropertyBlock' para alterar cores sem duplicar instâncias de materiais."}],"dicas_level_design":null}

